17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Map;
24	import java.util.Objects;
25	import java.util.stream.Collectors;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
37	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * The maximum number of owners that may be registered on any single day (by registration date).
66	     * Once this many owners already carry today's registration date, further creation is rejected.
67	     */
68	    private static final int MAX_OWNERS_PER_DAY = 20;
69	
70	    /**
71	     * The maximum number of owners permitted in any single city. Once a city already contains
72	     * this many owners, creating a further owner in that city is rejected. Cities are matched
73	     * ignoring letter case.
74	     */
75	    private static final int MAX_OWNERS_PER_CITY = 8;
76	
77	    /**
78	     * The number of owners, counted from the very first ever created, that receive the
79	     * {@code FOUNDING} membership tier. Owners created once this many already exist receive
80	     * the {@code STANDARD} tier instead.
81	     */
82	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
133	        if (owner.getRegistrationDate() == null) {
134	            owner.setRegistrationDate(LocalDate.now());
135	        }
136	        if (isDailyRegistrationLimitReached()) {
137	            throw new DailyOwnerRegistrationLimitException(
138	                "The maximum of " + MAX_OWNERS_PER_DAY
139	                    + " owners that may be registered today has already been reached");
140	        }
141	        if (isDuplicateTelephone(owner)) {
142	            throw new DuplicateOwnerException("An owner with telephone "
143	                + owner.getTelephone() + " already exists");
144	        }
145	        if (isDuplicateEmail(owner)) {
146	            throw new DuplicateOwnerException("An owner with email "
147	                + owner.getEmail() + " already exists");
148	        }
149	        if (isCityOwnerLimitReached(owner.getCity())) {
150	            throw new CityOwnerLimitException("The city " + owner.getCity()
151	                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
152	        }
153	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
154	        owner.setMembershipNumber(membershipNumber);
155	        owner.setMembershipTier(membershipNumber <= FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD");
156	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
157	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
158	        owner.setLocality(resolveLocality(owner.getCity()));
159	        owner.setCity(resolveCity(owner.getCity()));
160	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
161	        this.clinicService.saveOwner(owner);
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    /**
169	     * Determines whether the maximum number of owner registrations permitted for today has
170	     * already been reached. Owners are counted by registration date, comparing against the
171	     * current day, so the limit resets at midnight.
172	     *
173	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
174	     *         registration date
175	     */
176	    private boolean isDailyRegistrationLimitReached() {
177	        LocalDate today = LocalDate.now();
178	        long registeredToday = this.clinicService.findAllOwners().stream()
179	            .filter(existing -> today.equals(existing.getRegistrationDate()))
180	            .count();
181	        return registeredToday >= MAX_OWNERS_PER_DAY;
182	    }
183	
184	    /**
185	     * Determines whether the given city already contains the maximum number of owners permitted
186	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
187	     * city is never considered to have reached the limit.
188	     *
189	     * @param city the city of the owner about to be created
190	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
191	     *         given city
192	     */
193	    private boolean isCityOwnerLimitReached(String city) {
194	        if (city == null) {
195	            return false;
196	        }
197	        long ownersInCity = this.clinicService.findAllOwners().stream()
198	            .filter(existing -> existing.getCity() != null
199	                && existing.getCity().equalsIgnoreCase(city))
200	            .count();
201	        return ownersInCity >= MAX_OWNERS_PER_CITY;
202	    }
203	
204	    /**
205	     * Determines whether any other owner already uses the candidate's telephone number.
206	     * The comparison ignores letter case and surrounding or repeated whitespace.
207	     *
208	     * @param candidate the owner about to be created
209	     * @return {@code true} if an owner with the same telephone is already present in the data store
210	     */
211	    private boolean isDuplicateTelephone(Owner candidate) {
212	        String telephone = normalizeTelephone(candidate.getTelephone());
213	        return this.clinicService.findAllOwners().stream()
214	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
215	    }
216	
217	    /**
218	     * Canonicalises a telephone number by stripping every character that is not a digit
219	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
220	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
221	     * an owner and used for the telephone-uniqueness check.
222	     *
223	     * @param telephone the raw telephone value, possibly {@code null}
224	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
225	     */
226	    private static String normalizeTelephone(String telephone) {
227	        if (telephone == null) {
228	            return null;
229	        }
230	        return telephone.replaceAll("[^0-9]", "");
231	    }
232	
233	    /**
234	     * Determines whether any other owner already uses the candidate's email address.
235	     * An absent or blank email is never considered a duplicate. The comparison ignores
236	     * letter case and surrounding or repeated whitespace.
237	     *
238	     * @param candidate the owner about to be created
239	     * @return {@code true} if an owner with the same email is already present in the data store
240	     */
241	    private boolean isDuplicateEmail(Owner candidate) {
242	        String email = normalize(candidate.getEmail());
243	        if (email == null || email.isBlank()) {
244	            return false;
245	        }
246	        return this.clinicService.findAllOwners().stream()
247	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
248	    }
249	
250	    /**
251	     * Builds the customer code for a newly created owner, formatted as
252	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
253	     * owners already present in the same city, zero-padded to four digits
254	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
255	     *
256	     * @param city the city of the owner about to be created
257	     * @return the formatted customer code
258	     */
259	    /**
260	     * Resolves the city name to store for a newly created owner. The supplied city is
261	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
262	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
263	     * However, if an owner already exists in that city (matched ignoring letter case), that
264	     * existing owner's exact spelling of the city is reused instead, so a single canonical
265	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
266	     * rather than being flattened to {@code "Mcfarland"}).
267	     *
268	     * @param city the raw city supplied for the owner about to be created
269	     * @return the existing owner's spelling if the city is already known, otherwise the
270	     *         title-cased city; {@code null} if {@code city} was {@code null}
271	     */
272	    private String resolveCity(String city) {
273	        if (city == null) {
274	            return null;
275	        }
276	        return this.clinicService.findAllOwners().stream()
277	            .map(Owner::getCity)
278	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
279	            .findFirst()
280	            .orElseGet(() -> titleCase(city));
281	    }
282	
283	    /**
284	     * Converts a city name to title case: each whitespace-separated word has its first letter
285	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
286	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
287	     *
288	     * @param city the city to title-case
289	     * @return the title-cased city
290	     */
291	    private static String titleCase(String city) {
292	        StringBuilder result = new StringBuilder(city.length());
293	        boolean startOfWord = true;
294	        for (int i = 0; i < city.length(); i++) {
295	            char c = city.charAt(i);
296	            if (Character.isWhitespace(c)) {
297	                startOfWord = true;
298	                result.append(c);
299	            } else if (startOfWord) {
300	                result.append(Character.toTitleCase(c));
301	                startOfWord = false;
302	            } else {
303	                result.append(Character.toLowerCase(c));
304	            }
305	        }
306	        return result.toString();
307	    }
308	
309	    /**
310	     * Counts how many owners already present in the data store share the given last name,
311	     * ignoring letter case. This is evaluated before the new owner is saved, so it reflects
312	     * the number of <em>other</em> owners carrying that last name at creation time.
313	     *
314	     * @param lastName the last name of the owner about to be created
315	     * @return the number of existing owners with the same last name; {@code 0} if the last
316	     *         name is {@code null}
317	     */
318	    private int countNamesakes(String lastName) {
319	        if (lastName == null) {
320	            return 0;
321	        }
322	        return (int) this.clinicService.findAllOwners().stream()
323	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
324	            .count();
325	    }
326	
327	    /**
328	     * Determines whether another owner already resides at the same address and city as the owner
329	     * about to be created. Both address and city are matched ignoring letter case. This is
330	     * evaluated before the new owner is saved, so it reflects only owners that already existed.
331	     *
332	     * @param address the address of the owner about to be created
333	     * @param city    the city of the owner about to be created
334	     * @return {@code true} if an existing owner already has the same address and city
335	     */
336	    /**
337	     * Determines the locality of the owner about to be created relative to the existing clientele.
338	     * The result is {@code "local"} if the owner's city is the single most common city among all
339	     * owners that already exist, and {@code "remote"} otherwise. Cities are grouped ignoring letter
340	     * case. If there are no existing owners, or if two or more cities are tied for the most common
341	     * (so there is no single most common city), the result is {@code "remote"}.
342	     *
343	     * @param city the city of the owner about to be created
344	     * @return {@code "local"} if the city is the single most common among existing owners,
345	     *         otherwise {@code "remote"}
346	     */
347	    private String resolveLocality(String city) {
348	        if (city == null) {
349	            return "remote";
350	        }
351	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
352	            .map(Owner::getCity)
353	            .filter(Objects::nonNull)
354	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT),
355	                Collectors.counting()));
356	        long maxCount = countsByCity.values().stream()
357	            .mapToLong(Long::longValue)
358	            .max()
359	            .orElse(0L);
360	        if (maxCount == 0L) {
361	            return "remote";
362	        }
363	        List<String> mostCommonCities = countsByCity.entrySet().stream()
364	            .filter(entry -> entry.getValue() == maxCount)
365	            .map(Map.Entry::getKey)
366	            .toList();
367	        if (mostCommonCities.size() != 1) {
368	            return "remote";
369	        }
370	        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "local" : "remote";
371	    }
372	
373	    private boolean sharesHousehold(String address, String city) {
374	        if (address == null || city == null) {
375	            return false;
376	        }
377	        return this.clinicService.findAllOwners().stream()
378	            .anyMatch(existing -> address.equalsIgnoreCase(existing.getAddress())
379	                && city.equalsIgnoreCase(existing.getCity()));
380	    }
381	
382	    private String nextCustomerCode(String city) {
383	        long ownersInCity = this.clinicService.findAllOwners().stream()
384	            .filter(existing -> existing.getCity() != null
385	                && existing.getCity().equalsIgnoreCase(city))
386	            .count();
387	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
388	    }
389	
390	    /**
391	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
392	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
393	     * any run of internal whitespace is collapsed to a single space, and the result is
394	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
395	     * normalise to {@code "john smith"}.
396	     *
397	     * @param value the raw value, possibly {@code null}
398	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
399	     */
400	    private static String normalize(String value) {
401	        if (value == null) {
402	            return null;
403	        }
404	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Override
409	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
410	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
411	        if (currentOwner == null) {
